SELECT 



        (l.lead_no LIKE CONCAT('%', #{keyword}, '%') OR l.company LIKE CONCAT('%', #{keyword}, '%')
         OR l.contact_name LIKE CONCAT('%', #{keyword}, '%') OR l.phone LIKE CONCAT('%', #{keyword}, '%'))

    AND l.status = #{status}
    AND l.source = #{source}
    AND l.campaign_id = #{campaignId}
    AND l.owner_id = #{ownerId}

ORDER BY l.id DESC
